<?php
/** TEMP PS S1686 mf — DEPLOY: naujas mu-plugin petshop-sugrazinimas.php v1.0.0 + šablonas ps-sablonai/win-back-pakartoti.php + petshop-lifecycle-vartai.php v1.2.1 (win_back į vartų sąrašą; bak .bak_s1686); token_get_all, heartbeat, rollback. */
add_action('init', function(){
  if (!isset($_GET['ps_s1686mf'])) return; $o=array('v'=>'S1686 mf'); $mu=WPMU_PLUGIN_DIR; $f=$mu.'/petshop-sugrazinimas.php'; $t=$mu.'/ps-sablonai/win-back-pakartoti.php'; $v=$mu.'/petshop-lifecycle-vartai.php'; $bak=WP_CONTENT_DIR.'/uploads/ps-backups/petshop-lifecycle-vartai.php.bak_s1686';
  if(file_exists($f)||class_exists('Petshop_Sugrazinimas')||file_exists($t)){ $o['STOP']='vardas/klasė/šablonas užimti'; echo json_encode($o); exit; }
  if(substr(md5_file($v),0,8)!=='5d2ca9ae'){ $o['STOP']='vartai md5 ne v1.2.0: '.md5_file($v); echo json_encode($o); exit; }
  $np=base64_decode(''); $nt=base64_decode(''); $nv=base64_decode('');
  try { token_get_all($np, TOKEN_PARSE); token_get_all($nt, TOKEN_PARSE); token_get_all($nv, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']='ParseError: '.$e->getMessage(); echo json_encode($o); exit; }
  copy($v,$bak); file_put_contents($t,$nt); file_put_contents($v,$nv); file_put_contents($f,$np);
  if(function_exists('opcache_invalidate')){ foreach(array($f,$t,$v) as $x) opcache_invalidate($x,true); }
  $o['md5']=array('sugr'=>md5_file($f),'tpl'=>md5_file($t),'vartai'=>md5_file($v));
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code;
  if($code>=500||$code===0){ unlink($f); unlink($t); copy($bak,$v); $o['ROLLBACK']='atstatyta'; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
